from __future__ import print_function
import logging
import json
import os
import time

from .exceptions import (CellNotReady,
                         StatusNotSupportedByRap,
                         StatusNotSupported,
                         CertificateInstallationFailure)
from .pbts import site_conf_validation
from .common import StatusConfiguration

log = logging.getLogger(__name__)
log.addHandler(logging.NullHandler())


@site_conf_validation
class CloudBTS(object):
    SUBMODULE = 'c'
    NAME = 'mz'
    API_VER = 'v1'
    DEFAULT_NO = '1'

    def __init__(self, session):
        self.session = session

    def get_specific_url(self, *url_components):
        """Can be called from every MegaZone subclass to get more specific url."""
        components = [self.link()] + list(url_components)
        return '/'.join(components)

    def link(self):
        """Returns path to REST cloud resp"""
        return '/'.join([self.NAME, self.SUBMODULE, self.API_VER, 'cbts', self.DEFAULT_NO])

    def get_cbts_sw_release_name(self, timeout=None):
        """ Returns cloud software release name.
        for example: 5G19 """
        url = self.get_specific_url('swm/info')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()['releaseName']

    def get_cbts_sw_release_version(self, timeout=None):
        """ Returns cloud software version.
        for example: 0.135.376 """
        url = self.get_specific_url('swm/info')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()['cbtsSoftwareReleaseVersion']

    def get_startup_phase(self, timeout=None):
        """ Returns dict with information about startup Phase """
        url = self.get_specific_url('info')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()['startupPhase']

    def get_test_state(self, timeout=None):
        url = self.get_specific_url('testState')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()['state']

    def reset_site(self):
        url = self.get_specific_url('reset')
        payload = {"changedValues": {"resetRequest": "site", "resetUri": ""}}
        payload = json.dumps(payload)
        return self.session.send_request(url, method='PUT', data=payload, verify=False)

    def get_cell_info(self, number=None, attribute='availabilityStatus', timeout=None):
        return self.get_cell_specific_info(cell_number=number, attribute=attribute, timeout=timeout)

    def get_subcells_info(self, cell_number=1, subcell_number=None, attribute=None, timeout=None):
        subcells_info = self.get_subcells(local_cell=cell_number, timeout=timeout)
        if subcell_number is not None:
            subcell = subcells_info[subcell_number]
            return subcell[attribute] if attribute else subcell
        return [subcell_info[attribute] for subcell_info in subcells_info] if attribute else subcells_info

    def get_cell_specific_info(self, cell_number=None, attribute=None, timeout=None):
        if cell_number:
            cell = self._get_cell(cell_number, timeout=timeout)
            return cell if not attribute else cell[attribute]
        else:
            cells = self._get_cells(timeout=timeout)
            return cells if not attribute else [cell[attribute] for cell in cells]

    def _get_cell(self, number=1, timeout=None):
        url = self.get_cell_links(timeout=timeout)[number - 1]
        return self.session.send_request(url, timeout=timeout).json()

    def _get_cells(self, timeout):
        cells = [self.session.send_request(cell_link, timeout=timeout).json()
                 for cell_link in self.get_cell_links(timeout=timeout)]
        return cells

    def get_cell_links(self, timeout=None):
        url = self.get_specific_url('localCell')
        link_list = self.session.send_request(url, timeout=timeout).json()['_links']
        return [val.lstrip('/') for link in link_list for key, val in link.items()]

    def is_cell_online(self, endpoint, timeout=None):
        resp = self.session.send_request(endpoint, timeout=timeout)
        resp = resp.json()
        return (resp['planningStatus'] != 'planned'
                or resp['availabilityStatus'] == 'online')

    def verify_all_cells(self, timeout=None):
        endpoints = self.get_cell_links(timeout=timeout)
        if not all(self.is_cell_online(e, timeout=timeout) for e in endpoints):
            raise CellNotReady

    def get_s1_status(self, timeout=None):
        required_key = "availabilityStatus"
        url = self.get_specific_url('application/5g/links/s1/1')
        s1_status = self.session.send_request(url, timeout=timeout).json()
        return s1_status[required_key]

    def _get_local_cells_endpoints(self, local_cell=None, timeout=None):
        if local_cell:
            # TODO: change endpoint, get it from link method (after refactor)
            partial_url = 'localCell/{id}'.format(id=local_cell)
            return [self.get_specific_url(partial_url)]
        else:
            return self.get_cell_links(timeout=timeout)

    def get_local_cells(self, id=None, timeout=None):
        """ Get list of respons(es) to local cell endpoint(s). If no id given
        it returns repsonses of all local cells.
        :param id: local cell id, default is None.
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite)."""
        endpoints = self._get_local_cells_endpoints(local_cell=id, timeout=timeout)
        loc_cells = []
        for endpoint in endpoints:
            resp = self.session.send_request(endpoint, timeout=timeout)
            json_resp = resp.json()
            loc_cells.append(json_resp)
        return loc_cells

    def get_subcells(self, local_cell=None, timeout=None):
        """ Returns list of subcells for specified local_cell.
        :param local_cell: local cell id, default is None.
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite)."""
        local_cells = self.get_local_cells(id=local_cell, timeout=timeout)
        return [sub for lcell in local_cells for sub in lcell['subcells']]

    def get_vm_statuses(self, timeout=None):
        url = self.get_specific_url('/'.join(['vm/']))
        vm_json = self.session.send_request(url, timeout=timeout).json()
        # Return vm_json, but keys as vm types instead of identifiers
        return {vm_json[vm_id]['type']: value for vm_id, value in vm_json.items()}

    def get_vm_info(self, vm_attrib=None, timeout=None):
        url = self.get_specific_url('/'.join(['vm/']))
        vm_resp = self.session.send_request(url, timeout=timeout).json()

        return {vm_id:
                vm_data.get(vm_attrib) if vm_attrib is not None else vm_data
                for vm_id, vm_data in vm_resp.items()}

    def get_pools_configuration(self, timeout=None):
        url = self.get_specific_url('application/5g')
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()['config']['pools']

    def get_rap_interface(self, fsm_id='1', rap_id='1', timeout=None):
        url = self.get_specific_url('rap/{}'.format(rap_id))
        interface_obj = self.session.send_request(url, timeout=timeout).json()['interface'][fsm_id]
        return interface_obj

    def rap_reset(self, rap_id="1"):
        reset_url = '/mz/r/v1/reset'
        body = {"resetRequest": "rap",
                "resetUri": "/mz/c/v1/cbts/1/rap/{}".format(rap_id),
                "external": "true"}
        body = json.dumps(body)
        return self.session.send_request(reset_url, method='PUT', data=body)

    def get_rap_status(self, rap_id="1", timeout=None):
        status_key = "availabilityStatus"
        url = self.get_specific_url('rap/{}'.format(rap_id))
        rap_response = self.session.send_request(url, timeout=timeout).json()
        return rap_response[status_key]

    def get_rap(self, rap_id='1', timeout=None):
        url = self.get_specific_url('rap/{}'.format(rap_id))
        rap_obj = self.session.send_request(url, timeout=timeout).json()
        return rap_obj

    def wait_for_rap_availability(self, rap_id='1', timeout=1200.0, interval=1.0):
        end = time.time() + timeout
        rap_status_is_online = self._rap_status_is_online(rap_id)
        while not rap_status_is_online and not self._timeout_expired(end):
            time.sleep(interval)
            rap_status_is_online = self._rap_status_is_online(rap_id)

        return rap_status_is_online

    def _rap_status_is_online(self, rap_id):
        rap_status = self.get_rap_status(rap_id)
        return rap_status == 'online'

    @staticmethod
    def _timeout_expired(end):
        return end < time.time()

    def _get_rap_ids(self, timeout):
        rap_link = "_links"
        url = self.get_specific_url('rap')
        raps_response = self.session.send_request(url, timeout=timeout).json()
        rap_ids = []
        for rap_id in raps_response[rap_link]:
            rap_ids.append(os.path.basename(rap_id['href']))
        return rap_ids

    def _get_statuses_for_rap_id(self, rap_id, statuses_to_get, timeout=None):
        rap_status = {}
        rap_response = self.get_rap(rap_id, timeout=timeout)
        for status in statuses_to_get:
            try:
                rap_status[status] = rap_response[status]
            except KeyError:
                raise StatusNotSupportedByRap('Provided status {} is not supported by RAP'.format(status))
        return rap_status

    def get_rap_statuses(self, status_name=None, timeout=None):
        if status_name is None:
            statuses_to_get = StatusConfiguration.supported_rap_statuses
        else:
            if status_name not in StatusConfiguration.supported_rap_statuses:
                raise StatusNotSupported('Provided status {} is not supported'.format(status_name))
            statuses_to_get = [status_name]
        rap_ids = self._get_rap_ids(timeout=timeout)

        rap_statuses = {}

        for rap_id in rap_ids:
            statuses_for_rap = self._get_statuses_for_rap_id(rap_id, statuses_to_get, timeout=timeout)
            rap_statuses[rap_id] = statuses_for_rap
        return rap_statuses

    def get_bts_info(self, attribute=None, timeout=None):
        url = self.get_specific_url('info')
        resp = self.session.send_request(url, timeout=timeout)
        bts_info_json = resp.json()
        return bts_info_json[attribute] if attribute is not None else bts_info_json

    def add_additional_certificate(self, cert, rap_ids):
        """ Install a certificate on CU.

        :param cert: certificate string
        :param rap_ids: list of ids of raps that the certificate
                        will be added for.
        """
        url = self.get_specific_url('certMgmt', 'executeCommand')

        add_cert_cmd = 'addAdditionalCertificate'
        cmd_params = {"caCertificate": cert}
        target = (['RAC'] + ['/' + self.get_specific_url('rap', str(rap_id))
                             for rap_id in rap_ids])

        payload = {"operation": add_cert_cmd,
                   "params": cmd_params,
                   "target": target}
        response = self.session.send_request(url, method='PUT', json=payload)
        if response.status_code != 200:
            exc_msg = ("Failed to install a certificate:\n"
                       "Status code: {status_code}\n{response_json}")
            exc_msg = exc_msg.format(status_code=response.status_code,
                                     response_json=response.json())
            raise CertificateInstallationFailure(exc_msg)

    def get_certificate_signing_request_for_vnf(self):
        url = self.get_specific_url('certMgmt', 'executeCommand')
        payload = {"operation": "createCertificateSigningRequest", "target": ["RAC"]}
        payload = json.dumps(payload)
        return self.session.send_request(url, method='PUT', data=payload, verify=False)

    def _set_administrative_state(self, cell_id, state):
        url = self.get_specific_url('localCell/{}'.format(cell_id))
        body = {'administrativeState': state}
        body = json.dumps(body)
        return self.session.send_request(url, method='PUT', data=body)

    def cell_lock(self, cell_id):
        self._set_administrative_state(cell_id, 'locked')

    def cell_unlock(self, cell_id):
        self._set_administrative_state(cell_id, 'unlocked')

    def activate_vnf_mode(self, timeout):
        mode = 'activate'
        return self._change_vnf_mode(mode, timeout)

    def deactivate_vnf_mode(self, timeout):
        mode = 'deactivate'
        return self._change_vnf_mode(mode, timeout)

    def _change_vnf_mode(self, mode, timeout):
        url = self.get_specific_url('vnfActivityMode')
        body = {'targetVnfActivityMode': mode}
        data = json.dumps(body)
        return self.session.send_request(url, method='PUT', data=data, timeout=timeout)


class VM(CloudBTS):
    def link(self):
        """Returns path to REST VM resp given by index"""
        return '/'.join([super(VM, self).link(), 'vm', ''])

    def _get_all_vm_info(self):
        resp = self.session.send_request(self.link())
        return resp.json()

    def get_all_vm_types(self, timeout=None):
        """Returns list of all vm types."""
        urls = self.get_all_vms_urls()
        tmp = []
        for vm in urls:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            tmp.append(resp['type'])
        return tmp

    def get_all_vms_urls(self):
        """Returns list of all vm urls."""
        resp_dict = self._get_all_vm_info()
        return [x['moAddress']['uri'] for x in resp_dict.values() if 'fullOwnerNode' in x]

    def get_ip(self, timeout=None):
        vms = self.get_all_vms_urls()
        tmp = {}
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            tmp[resp['type']] = resp['ipAddress']
        return tmp

    def get_hostname(self, timeout=None):
        vms = self.get_all_vms_urls()
        tmp = {}
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            tmp[resp['type']] = resp['hostname']
        return tmp

    def get_vm_availability_status(self, vm_name, timeout=None):
        vms = self.get_all_vms_urls()
        availability_status = None
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            if resp['type'] == vm_name:
                availability_status = resp['availabilityStatus']
        if availability_status is None:
            raise KeyError(availability_status)
        return str(availability_status)

    def get_vms_availability_status(self, timeout=None):
        vms = self.get_all_vms_urls()
        tmp = {}
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            tmp[resp['type']] = resp['availabilityStatus']
        return tmp

    def get_procedural_status(self, vm_name, timeout=None):
        vms = self.get_all_vms_urls()
        procedural_status = None
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            if resp['type'] == vm_name:
                procedural_status = resp['proceduralStatus']
        if procedural_status is None:
            raise KeyError(procedural_status)
        return str(procedural_status)

    def get_cloud_device_status(self, vm_name, timeout=None):
        vms = self.get_all_vms_urls()
        cloud_device_status = None
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            if resp['type'] == vm_name:
                cloud_device_status = resp['cloudDeviceStatus']
        if cloud_device_status is None:
            raise KeyError(cloud_device_status)
        return str(cloud_device_status)

    def get_cloud_devices_status(self, vm_name, timeout=None):
        vms = self.get_all_vms_urls()
        cloud_devices_status = {}
        for vm in vms:
            vm_url = os.path.basename(vm)
            resp = self.session.send_request(self.link() + str(vm_url), timeout=timeout).json()
            vm_type = resp['type']
            if vm_name.upper() in vm_type.upper():
                cloud_devices_status[vm_type] = resp['cloudDeviceStatus']
        if cloud_devices_status is None:
            raise KeyError(cloud_devices_status)
        return cloud_devices_status
